import{_ as s,o as t,c as a,a0 as d}from"./chunks/framework.B9sLprCo.js";const k=JSON.parse('{"title":"实操手册：添加 workspace 包","description":"","frontmatter":{"editSource":"docs/cookbook/adding-a-package.md"},"headers":[],"relativePath":"reference/cookbook/adding-a-package.md","filePath":"reference/cookbook/adding-a-package.md"}'),n={name:"reference/cookbook/adding-a-package.md"};function i(o,e,c,p,r,l){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="实操手册-添加-workspace-包" tabindex="-1">实操手册：添加 workspace 包 <a class="header-anchor" href="#实操手册-添加-workspace-包" aria-label="Permalink to &quot;实操手册：添加 workspace 包&quot;">​</a></h1><p>为新建 <code>@deepseek-ai/dsh-&lt;name&gt;</code> 包提供的逐文件清单。本清单以 bash 和适配器这两个包为模板进行验证；如果清单与模板有出入，请在此修正。</p><h2 id="_1-创建包" tabindex="-1">1. 创建包 <a class="header-anchor" href="#_1-创建包" aria-label="Permalink to &quot;1. 创建包&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/&lt;group&gt;/&lt;pkg&gt;/</span></span>
<span class="line"><span> package.json # copy from packages/core/tools, adjust name/description/deps</span></span>
<span class="line"><span> tsconfig.json # extends../../../tsconfig.base.json, rootDir src,</span></span>
<span class="line"><span> # outDir lib/types, references:../../../vendor/cosmokit,</span></span>
<span class="line"><span> #../../../vendor/cordis (+../../../vendor/schemastery if</span></span>
<span class="line"><span> # you use Config, +../../&lt;group&gt;/&lt;dep&gt; for each dsh dep)</span></span>
<span class="line"><span> src/index.ts # service default export or plugin (name/inject/apply/Config)</span></span>
<span class="line"><span> README.md # service API, events, extension points, design notes,</span></span>
<span class="line"><span> # + Model Experience context blocks or the short form</span></span>
<span class="line"><span> # + the &quot;Known Limitations and Deferred Work&quot; section</span></span>
<span class="line"><span> # (or one sentence saying there are none)</span></span></code></pre></div><p>当已有分组与包的角色匹配时，选择该分组（<code>core</code>、<code>llm</code>、<code>bash</code>、<code>compact</code>、<code>subagent</code>、<code>todo</code>、<code>session-persistence</code>、<code>ui</code>、<code>util</code> 或 <code>support</code>）。允许新建分组，但分组只是纯容器：没有 <code>package.json</code>，没有源文件，包仍然恰好位于其下一层。</p><p>package.json 不变式（由 <code>pnpm run constraints</code> / <code>scripts/check-workspace-constraints.ts</code> 强制执行）：<code>private: true</code>，<code>version</code> 与根 <code>package.json</code> 一致，<code>type: module</code>，<code>main: &quot;lib/index.js&quot;</code>，<code>types: &quot;lib/types/index.d.ts&quot;</code>，<code>exports[&quot;.&quot;].types: &quot;./lib/types/index.d.ts&quot;</code>，<code>exports[&quot;.&quot;].default: &quot;./lib/index.js&quot;</code>，<code>@deepseek-ai/cordis</code> 同时出现在 peerDependencies 和 devDependencies 中（相同范围）。每个 dsh 对等依赖（peer dependency）都要在 devDependencies 中镜像。<code>@deepseek-ai/schemastery</code> 放在 <code>dependencies</code> 中（它是运行时校验器），与 agent-loop 保持一致。<code>files</code> 列表精确包含 <code>lib/index.js</code>、<code>lib/invariant.js</code>、<code>lib/types/**/*.d.ts</code> 以及门禁认可的包专用运行时产物；如果包的运行时 export 指向输出树，还要包含 <code>lib/types/**/*.js</code>。不要发布 <code>src</code>、声明映射、JS map 或陈旧的根声明文件。带有 <code>bin</code> 的 CLI 应用包在 <code>files</code> 中将 <code>lib/bin.js</code> 紧跟在 <code>lib/index.js</code> 之后。</p><p>包内的相对导入在源码中使用显式 <code>.ts</code> 后缀（例如 <code>export * from &#39;./types.ts&#39;</code>）。编译器在输出的 JS 中将其重写为 <code>.js</code>，在声明文件中保留显式 <code>.ts</code> 后缀；标准的 NodeNext/Node16 TypeScript 消费方会将其解析到同目录的 <code>.d.ts</code> 文件。</p><h2 id="_2-在根配置中注册" tabindex="-1">2. 在根配置中注册 <a class="header-anchor" href="#_2-在根配置中注册" aria-label="Permalink to &quot;2. 在根配置中注册&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>变更</th></tr></thead><tbody><tr><td><code>tsconfig.base.json</code></td><td>已有分组无需编辑；新分组需为 <code>@deepseek-ai/dsh-*</code> 通配符添加 <code>./packages/&lt;group&gt;/*/src</code> 候选路径</td></tr><tr><td><code>tsconfig.host.json</code>（Host 包）或 <code>tsconfig.client.json</code>（Client 包）</td><td>在 <code>references</code> 中添加 <code>{ &quot;path&quot;: &quot;./packages/&lt;group&gt;/&lt;pkg&gt;&quot; }</code>——普通包恰好属于一个 aggregate，绝不两个都加。<code>api/remotes</code> 因 Host 生成约定与 Client 消费约定之间存在顺序依赖而使用仓库专属拆分，新增包不得仿照（<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/development.md#typescript-project-layout" target="_blank" rel="noreferrer">布局</a>）</td></tr><tr><td><code>knip.json</code></td><td>仅当包有仓库发现机制尚未覆盖的入口时需要</td></tr></tbody></table><p><code>packages/client/*</code> 包改为 extends <code>tsconfig.base.client.json</code>（而非 <code>tsconfig.base.json</code>）；client 插件包还需在 package.json 声明 <code>dsh.client</code>、导出 <code>./client</code>、调用共享 tsdown preset（<code>packages/client/tsdown.client.ts</code>）——client 侧见 <a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/packages/client/AGENTS.md" target="_blank" rel="noreferrer">packages/client/AGENTS.md</a>。</p><p>以下内容由 glob 或包 manifest（元数据清单）发现机制自动覆盖，无需手动编辑：根 <code>package.json</code> workspaces、<code>scripts/publint-all.ts</code>、<code>tsdown.config.ts</code>、<code>.oxlintrc.json</code>、<code>scripts/check-workspace-constraints.ts</code>。</p><h2 id="_3-确定包拓扑" tabindex="-1">3. 确定包拓扑 <a class="header-anchor" href="#_3-确定包拓扑" aria-label="Permalink to &quot;3. 确定包拓扑&quot;">​</a></h2><p>对于可替换的能力，当 Service Definition／Service Provider／Consumer 角色需要独立演进时，将它们拆分到不同包中（见 docs/architecture.md § &quot;Capability seams&quot;——shell 三组件是模板）。单一用途的插件保持为一个包。</p><h3 id="使用符合实际的角色名称" tabindex="-1">使用符合实际的角色名称 <a class="header-anchor" href="#使用符合实际的角色名称" aria-label="Permalink to &quot;使用符合实际的角色名称&quot;">​</a></h3><p>名称必须描述当前稳定职责。不要用首个实现、可能的未来扩展或 Cordis 基类命名。接口包使用能力名称。实现包加上能够区分实现的机制、协议、环境或厂商限定词。只有同主机执行属于约定时，才使用 <code>local</code>。</p><p>一个 engine、runtime、policy、controller、resolver、store 或当前配置使用单数 <code>ctx</code> key。registry 或拥有多个具名成员的服务使用复数 key。类的角色与 key 的单复数必须一致。不得让不兼容的 host 与 client 声明复用同一个 Cordis <code>Context</code> key。即使二者使用独立的运行时 context，TypeScript 声明合并仍会同时看到两种类型。如果自然复数已经属于另一个端面，就增加职责后缀。</p><table tabindex="0"><thead><tr><th>词</th><th>适用条件</th><th>不适用条件</th></tr></thead><tbody><tr><td><code>Controller</code></td><td>接受命令或用户意图，并改变一项既有领域状态或展示状态。</td><td>执行任意工作、拥有一组 provider，或只把值转换为展示形式。</td></tr><tr><td><code>Store</code></td><td>拥有一组数据，主要提供该数据的 CRUD、snapshot 或 subscription 操作。</td><td>校验状态机、裁决权限、分派工作或拥有 provider 优先级。类中有 map 不等于 store。</td></tr><tr><td><code>Directory</code></td><td>暴露供发现或选择的条目及其元数据。</td><td>producer 向其中注册任意实现，或调用方通过它执行工作。</td></tr><tr><td><code>Presenter</code></td><td>将领域值或工具参数纯转换为渲染意图。</td><td>执行 I/O、订阅、修改状态或拥有生命周期。</td></tr><tr><td><code>Registry</code></td><td>拥有一组动态具名注册，以及查询、重复项或优先级规则、生命周期和释放。</td><td>主要约定是分派、执行、取消、策略或编排。</td></tr><tr><td><code>Runtime</code></td><td>运行实时工作，并跨调用拥有分派、取消、provider 协调或操作生命周期。</td><td>只存储记录、返回目录、解析一个值或保存配置。</td></tr><tr><td><code>Resolver</code></td><td>根据输入计算或定位一个答案，但不拥有该答案的生命周期。</td><td>拥有可变集合或长时间运行的执行过程。</td></tr><tr><td><code>Binder</code></td><td>把一个已声明接口绑定到调用方的 context 或生命周期，并返回绑定值。</td><td>把该值作为集合持有、控制其领域状态，或只转换数据。</td></tr><tr><td><code>Engine</code></td><td>实现领域算法或有状态执行模型。</td><td>只选择 provider 或跨协议边界转发请求。</td></tr><tr><td><code>Policy</code></td><td>决定允许、选择、限制或观察什么。</td><td>执行该决定所允许的机制。</td></tr><tr><td><code>Executor</code></td><td>在一项能力中运行一个明确请求或已解析 spec。</td><td>拥有广泛应用生命周期或 provider 目录。</td></tr><tr><td><code>Gateway</code></td><td>适配进程、网络、RPC 或 API 边界。</td><td>只注册同进程服务或存储元数据。</td></tr><tr><td><code>Provider</code></td><td>提供一项能力定义的一个实现。存在多个实现时，加上机制或厂商限定词。</td><td>表示能力定义、provider registry 或消费方 runtime。</td></tr><tr><td><code>Backend</code></td><td>在已定义接口之后实现可替换的底层持久化、传输或执行。</td><td>表示面向用户的服务或一个已返回的实时资源引用。</td></tr><tr><td><code>Handle</code></td><td>引用一个实时资源，并控制或观察该资源。</td><td>创建并管理完整资源池。</td></tr><tr><td><code>Config</code></td><td>拥有一个已解析配置值，或一项边界严格的配置记录及其更新约定。</td><td>存储通用集合、执行工作或暴露无关设置。</td></tr><tr><td><code>Service</code></td><td>拥有一项无法用以上更精确角色诚实描述的内聚领域服务。</td><td>只因为类继承 Cordis <code>Service</code> 而使用该名称。</td></tr></tbody></table><p>只对受支持的 Python 与 TypeScript SDK 所使用的 JSON-RPC 客户端／服务器协议使用 <code>SDK</code>。DeepSeek Harness 本身是 agent harness，不是 SDK 项目。产品拼写统一使用 <code>Typert</code>，不得使用 <code>TypeRT</code> 或 <code>typeRT</code>。</p><h2 id="_4-编写包-readme" tabindex="-1">4. 编写包 README <a class="header-anchor" href="#_4-编写包-readme" aria-label="Permalink to &quot;4. 编写包 README&quot;">​</a></h2><p>将包特有的服务 API、配置、事件、扩展点和设计说明放在前面。间接的 Model Experience 语句可以点名暴露本包贡献的消费方，但不重述该消费方的实现。包 README 以如下规范序列结尾：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Model Experience</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Request context and condition</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### What the model sees</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">The exact data-dependent fields, an anchored generated-catalog link, or an introduction to the verbatim literal below.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">##### Verbatim text for this field, when needed</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`markdown</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Stable system-prompt prose of any length, or another long non-generated literal, copied exactly from source.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### Token effect</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Fixed, conditional, retained, replaced, capped, or zero-direct token effect.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">#### KV Cache effect</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Append-only, prefix-stable, replacing, or independent behavior, including the exact conditions that may invalidate reuse.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Known Limitations and Deferred Work</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Consumer-visible gap**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> — exact missing operation or case, its consequence, and any maintainer constraint.</span></span></code></pre></div><p>根据实现填写 Model Experience。每个直接、条件、上限、生命周期或辅助的模型上下文条目使用一个 H3，包含上述三个有序 H4 字段，每个字段下有一个正文段落。引用包拥有的稳定文本：系统提示词放在引出它的字段下，用带标题的 H5 加 <code>markdown</code> 围栏表示，通常归入 <code>What the model sees</code>；其他短文本以命名占位符内联，其他长文本使用相同的嵌套形式。仅概述数据依赖或提供方拥有的文本。工具 schema 条目链接到生成的<a href="./../tool-catalog">工具目录</a>中对应的锚定章节，仅说明该处缺失的差异。当作用域可以隐藏 prompt 或 schema 其中之一而不影响另一个时，将二者分开。填写 <code>KV Cache effect</code> 时，应区分仅追加增长、稳定重复的前缀、替换既有请求 token 和独立模型请求，并列出会使缓存复用失效、且由本包拥有的变化。“不使缓存失效”仅表示本包保留了已有的可复用前缀；缓存是否可用以及何时淘汰不属于本包约定。<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/.agents/skills/dsh-prose-standard/SKILL.md" target="_blank" rel="noreferrer">行文标准</a>约束完整性与归属；章节结构由评审把关。</p><p>没有上下文效果或仅有消费方拥有路径的包写一句 <code>None, as...</code> 或 <code>Indirectly, through...</code>，随后添加 <code>KV Cache effect</code> H4 和一个非空正文段落；与模型无关的通用包用一句话说明模型看不到它的原因。两种情况都不要展开为对另一个包工作的描述。Known Limitations 一节独立维护。 记录了设计动机。</p><h2 id="_5-验证" tabindex="-1">5. 验证 <a class="header-anchor" href="#_5-验证" aria-label="Permalink to &quot;5. 验证&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # registers the workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> constraints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hygiene</span></span></code></pre></div><p>请遵循<a href="https://github.com/deepseek-ai/deepseek-harness/blob/master/docs/testing.md" target="_blank" rel="noreferrer">仓库测试政策</a>，执行新包所需的行为专项检查并达到相应覆盖率。</p>`,26)])])}const g=s(n,[["render",i]]);export{k as __pageData,g as default};
